import { BALANCE } from './balanceConfig';
import { cumulativeXpForLevel } from './formulas';

/**
 * Milestone-title levels: front-loaded, ever-widening, generated by
 * gap(k) = min(k, 8) starting from level 1 (level 1 itself is never a
 * milestone). Produces 2, 4, 7, 11, 16, 22, 29, 37, 45, 53, ... — matches
 * openspec/changes/virtual-dog-companion/design.md's "Milestone titles"
 * decision, validated there against the real XP curve. No fixed final
 * entry: the sequence keeps computing indefinitely (bounded only by
 * BALANCE.leveling.maxLevel), satisfying the "no final stage" guardrail in
 * proposal.md.
 */
function milestoneLevelAtIndex(index: number): number {
  let level = 1;
  for (let k = 1; k <= index; k++) {
    level += Math.min(k, 8);
  }
  return level;
}

/** 1-based index of `level` in the milestone sequence, or null if `level` isn't a milestone. Level 1 (the baseline every player starts at) is never itself a milestone. */
export function milestoneIndexForLevel(level: number): number | null {
  if (level <= 1) {
    return null;
  }
  let current = 1;
  let index = 0;
  let k = 1;
  while (current < level && current < BALANCE.leveling.maxLevel) {
    current += Math.min(k, 8);
    k++;
    index++;
  }
  return current === level ? index : null;
}

export function isMilestoneLevel(level: number): boolean {
  return milestoneIndexForLevel(level) !== null;
}

/**
 * Game-master-authored milestone titles, in level order (index 0 = the
 * first milestone level, level 2). Per
 * openspec/changes/virtual-dog-companion/tasks.md task 5.3: "Get
 * game-master-authored copy for the first 8 titles before shipping (do not
 * invent placeholder title copy)." No titles have been authored yet, so
 * this stays empty and titleForLevel() returns null for every level — no
 * milestone-title or cliffhanger UI renders until this is populated with
 * real copy. The milestone LEVEL FORMULA above is fully built and tested
 * independent of this array; only the copy is missing.
 */
export const MILESTONE_TITLES: string[] = [];

/** The authored title for `level`, or null if `level` isn't a milestone or has no authored copy yet. */
export function titleForLevel(level: number): string | null {
  const index = milestoneIndexForLevel(level);
  if (index === null || index < 1 || index > MILESTONE_TITLES.length) {
    return null;
  }
  return MILESTONE_TITLES[index - 1];
}

/**
 * Pure trigger condition for the one-away cliffhanger (design.md: "fires at
 * walk-close when xpToNextLevel <= trailing 5-walk average XP and the next
 * level is a milestone level"). Deliberately independent of title copy —
 * callers must separately confirm titleForLevel(level + 1) is non-null
 * before actually surfacing the cliffhanger, so this function's behavior
 * (and its tests) don't depend on whether milestone copy has shipped yet.
 */
export function shouldFireCliffhanger(level: number, xp: number, trailingAverageXp: number): boolean {
  const { maxLevel } = BALANCE.leveling;
  if (level >= maxLevel) {
    return false;
  }
  const nextLevel = level + 1;
  if (!isMilestoneLevel(nextLevel)) {
    return false;
  }
  const xpToNextLevel = cumulativeXpForLevel(nextLevel) - xp;
  return xpToNextLevel <= trailingAverageXp;
}
